package io.github.ningpp.compat;

/** Replacement for System.Management.ManagementException (generated by CSharpToJava converter). */
public class ManagementException extends SystemException {
    public ManagementException() { super(); }
    public ManagementException(String message) { super(message); }
    public ManagementException(String message, Throwable cause) { super(message, cause); }
}
